-- PREPARATION ONLY. Separate exact local approval and maintenance window required.
-- Private pinned package is mandatory; no operator payload is embedded here.
-- Parameters: @RepairPackage nvarchar(max), @MaintenanceWindowConfirmed bit.
IF @@LOCK_TIMEOUT<>-1 THROW 51155,'LOCAL54F requires a fresh session with its default lock timeout.',1;
IF @@TRANCOUNT<>0 OR (@@OPTIONS&2)=2 THROW 51155,'LOCAL54F requires its own explicit transaction.',1;
IF ISNULL(@MaintenanceWindowConfirmed,0)<>1 THROW 51155,'LOCAL54F requires owner-confirmed no-unsaved-checkout/no-concurrent-DDL maintenance window.',1;
IF @RepairPackage IS NULL OR ISJSON(@RepairPackage)<>1 OR DATALENGTH(@RepairPackage)>4194304 OR CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@RepairPackage)),2)<>N'70E129C2E622811731EBDB4C1E1FE2E20069D4C1D4283F63590408D12776A55F' THROW 51155,'LOCAL54F private package missing or changed.',1;
