IF HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','CONTROL')<>1 THROW 51155,'LOCAL54F needs authorized database maintenance access.',1;
DECLARE @HadXactAbort bit=CASE WHEN (@@OPTIONS&16384)=16384 THEN 1 ELSE 0 END;
SET LOCK_TIMEOUT 2000;SET XACT_ABORT ON;
