 INSERT @Proposed SELECT N'shifts' table_name,source.id,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'shifts|')+cells.facts)),2) signature FROM @S_shifts source  CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'id',LOWER(CONVERT(nvarchar(36),source.[id]))),(1,N'store_id',CONVERT(nvarchar(max),source.[store_id])),(2,N'terminal_id',CONVERT(nvarchar(max),source.[terminal_id])),(3,N'terminal_name',CONVERT(nvarchar(max),source.[terminal_name])),(4,N'opened_by_name',CONVERT(nvarchar(max),source.[opened_by_name])),(5,N'opened_by_staff_id',CONVERT(nvarchar(max),source.[opened_by_staff_id])),(6,N'opened_by_role',CONVERT(nvarchar(max),source.[opened_by_role])),(7,N'closed_by_name',CONVERT(nvarchar(max),source.[closed_by_name])),(8,N'closed_by_staff_id',CONVERT(nvarchar(max),source.[closed_by_staff_id])),(9,N'closed_by_role',CONVERT(nvarchar(max),source.[closed_by_role])),(10,N'opened_at',CONVERT(nvarchar(40),source.[opened_at],127)),(11,N'closed_at',CONVERT(nvarchar(40),source.[closed_at],127)),(12,N'opening_float',CONVERT(nvarchar(max),source.[opening_float])),(13,N'counted_cash',CONVERT(nvarchar(max),source.[counted_cash])),(14,N'expected_cash',CONVERT(nvarchar(max),source.[expected_cash])),(15,N'note',CONVERT(nvarchar(max),source.[note])),(16,N'overdue',CONVERT(nvarchar(1),source.[overdue])),(17,N'created_at',CONVERT(nvarchar(40),source.[created_at],127)),(18,N'updated_at',CONVERT(nvarchar(40),source.[updated_at],127)),(19,N'status',CONVERT(nvarchar(max),source.[status])),(20,N'closing_float',CONVERT(nvarchar(max),source.[closing_float])),(21,N'user_id',LOWER(CONVERT(nvarchar(36),source.[user_id]))),(22,N'row_version',CONVERT(nvarchar(max),source.[row_version])),(23,N'counted_card',CONVERT(nvarchar(max),source.[counted_card])),(24,N'counted_digital',CONVERT(nvarchar(max),source.[counted_digital])),(25,N'expected_card',CONVERT(nvarchar(max),source.[expected_card])),(26,N'expected_digital',CONVERT(nvarchar(max),source.[expected_digital])),(27,N'variance_cash',CONVERT(nvarchar(max),source.[variance_cash])),(28,N'variance_card',CONVERT(nvarchar(max),source.[variance_card])),(29,N'variance_digital',CONVERT(nvarchar(max),source.[variance_digital])),(30,N'variance_total',CONVERT(nvarchar(max),source.[variance_total])),(31,N'state',CONVERT(nvarchar(max),source.[state])),(32,N'close_reason',CONVERT(nvarchar(max),source.[close_reason])),(33,N'closing_started_at',CONVERT(nvarchar(40),source.[closing_started_at],127)),(34,N'closing_started_by',CONVERT(nvarchar(max),source.[closing_started_by])),(35,N'final_counted_cash',CONVERT(nvarchar(max),source.[final_counted_cash])),(36,N'variance_status',CONVERT(nvarchar(max),source.[variance_status]))) c(ordinal,name,value)) cells 
