 BEGIN TRANSACTION;
 SELECT @Lock=COUNT_BIG(*) FROM dbo.[audit_logs] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[held_orders] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[local_operation_receipts] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[pos_sync_shift_baselines] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[pos_sync_shift_closing_starts] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[pos_sync_shift_intents] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shift_cash_counts] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shift_close_events] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shift_notifications] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shift_reconciliations] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shift_variance_alerts] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[shifts] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[sync_change_journal] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
SELECT @Lock=COUNT_BIG(*) FROM dbo.[sync_checkpoints] WITH(TABLOCKX,HOLDLOCK,NOWAIT);
 INSERT @ActualMeta SELECT N'columns',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'columns|')+canonical.facts)),2) FROM (SELECT t.name table_name,c.column_id,c.name column_name,ty.name type_name,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,c.is_computed,c.collation_name FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'column_id',(CONVERT(nvarchar(max),s.[column_id])) COLLATE DATABASE_DEFAULT),(2,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT),(3,N'type_name',(CONVERT(nvarchar(max),s.[type_name])) COLLATE DATABASE_DEFAULT),(4,N'max_length',(CONVERT(nvarchar(max),s.[max_length])) COLLATE DATABASE_DEFAULT),(5,N'precision',(CONVERT(nvarchar(max),s.[precision])) COLLATE DATABASE_DEFAULT),(6,N'scale',(CONVERT(nvarchar(max),s.[scale])) COLLATE DATABASE_DEFAULT),(7,N'is_nullable',(CASE WHEN s.[is_nullable] IS NULL THEN NULL WHEN s.[is_nullable]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(8,N'is_identity',(CASE WHEN s.[is_identity] IS NULL THEN NULL WHEN s.[is_identity]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(9,N'is_computed',(CASE WHEN s.[is_computed] IS NULL THEN NULL WHEN s.[is_computed]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(10,N'collation_name',(CONVERT(nvarchar(max),s.[collation_name])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
