L WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(7,N'has_filter',(CASE WHEN s.[has_filter] IS NULL THEN NULL WHEN s.[has_filter]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(8,N'filter_definition',(CONVERT(nvarchar(max),s.[filter_definition])) COLLATE DATABASE_DEFAULT),(9,N'index_column_id',(CONVERT(nvarchar(max),s.[index_column_id])) COLLATE DATABASE_DEFAULT),(10,N'key_ordinal',(CONVERT(nvarchar(max),s.[key_ordinal])) COLLATE DATABASE_DEFAULT),(11,N'is_descending_key',(CASE WHEN s.[is_descending_key] IS NULL THEN NULL WHEN s.[is_descending_key]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(12,N'is_included_column',(CASE WHEN s.[is_included_column] IS NULL THEN NULL WHEN s.[is_included_column]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(13,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'foreign_keys',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'foreign_keys|')+canonical.facts)),2) FROM (SELECT t.name table_name,f.name,OBJECT_NAME(f.referenced_object_id) referenced_table,f.is_disabled,f.is_not_trusted,f.delete_referential_action_desc,f.update_referential_action_desc,fc.constraint_column_id,c.name column_name,rc.name referenced_column FROM sys.tables t JOIN sys.foreign_keys f ON f.parent_object_id=t.object_id JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id JOIN sys.columns c ON c.object_id=fc.parent_object_id AND c.column_id=fc.parent_column_id JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'referenced_table',(CONVERT(nvarchar(max),s.[referenced_table])) COLLATE DATABASE_DEFAULT),(3,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(4,N'is_not_trusted',(CASE WHEN s.[is_not_trusted] IS NULL THEN NULL WHEN s.[is_not_trusted]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(5,N'delete_referential_action_desc',(CONVERT(nvarchar(max),s.[delete_referential_action_desc])) COLLATE DATABASE_DEFAULT),(6,N'update_referential_action_desc',(CONVERT(nvarchar(max),s.[update_referential_action_desc])) COLLATE DATABASE_DEFAULT),(7,N'constraint_column_id',(CONVERT(nvarchar(max),s.[constraint_column_id])) COLLATE DATABASE_DEFAULT),(8,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT),(9,N'referenced_column',(CONVERT(nvarchar(max),s.[referenced_column])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'keys',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'keys|')+canonical.facts)),2) FROM (SELECT t.name table_name,k.name,k.type_desc,k.unique_index_id FROM sys.tables t JOIN sys.key_constraints k ON k.parent_object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'type_desc',(CONVERT(nvarchar(max),s.[type_desc])) COLLATE DATABASE_DEFAULT),(3,N'unique_index_id',(CONVERT(nvarchar(max),s.[unique_index_id])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'triggers',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'triggers|')+canonical.facts)),2) FROM (SELECT t.name table_name,tr.name,tr.is_disabled,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(tr.object_id))),2) definition_sha256,OBJECT_DEFINITION(tr.object_id) definition FROM sys.tables t JOIN sys.triggers tr ON tr.parent_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(3,N'definition_sha256',(CONVERT(nvarchar(max),s.[definition_sha256])) COLLATE DATABASE_DEFAULT),(4,N'definition',(CONVERT(nvarchar(max),s.[definition])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'tracking',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'tracking|')+canonical.facts)),2) FROM (SELECT t.name table_name,ct.is_track_columns_updated_on FROM sys.tables t JOIN sys.change_tracking_tables ct ON ct.object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'is_track_columns_updated_on',(CASE WHEN s.[is_track_columns_updated_on] IS NULL THEN NULL WHEN s.[is_track_columns_updated_on]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
 IF EXISTS(SELECT kind,signature,COUNT_BIG(*) n FROM @ActualMeta GROUP BY kind,signature EXCEPT SELECT kind,signature,COUNT_BIG(*) FROM @ExpectedMeta GROUP BY kind,signature) OR EXISTS(SELECT kind,signature,COUNT_BIG(*) FROM @ExpectedMeta GROUP BY kind,signature EXCEPT SELECT kind,signature,COUNT_BIG(*) FROM @ActualMeta GROUP BY kind,signature) THROW 51155,'LOCAL54F schema/default/constraint/index/trigger metadata changed.',1;
 IF OBJECT_ID(N'dbo.pos_sync_shift_author_attestations') IS NOT NULL THROW 51155,'LOCAL54F unexpected author receipt table.',1;
 IF EXISTS(SELECT 1 FROM dbo.pos_sync_shift_closing_starts WHERE branch_id=@Branch AND shift_id=@Shift) OR EXISTS(SELECT 1 FROM dbo.pos_sync_shift_intents WHERE branch_id=@Branch AND shift_id=@Shift) OR EXISTS(SELECT 1 FROM dbo.pos_sync_shift_baselines WHERE branch_id=@Branch AND shift_id=@Shift) THROW 51155,'LOCAL54F target has protected local history.',1;
 IF EXISTS(SELECT 1 FROM dbo.sync_change_journal WHERE acknowledged_at IS NULL AND (branch_id IS NULL OR branch_id=N'global' OR branch_id=@Branch) AND (entity_type IN(N'shifts',N'shift_cash_counts',N'shift_reconciliations',N'shift_close_events',N'shift_notifications',N'shift_variance_alerts',N'sales',N'sale_items',N'bookings',N'booking_payments',N'payment_transactions',N'held_orders') OR branch_id IS NULL OR branch_id=N'global')) THROW 51155,'LOCAL54F pending or unattributable local work.',1;
 SELECT @Lock=COUNT_BIG(*) FROM dbo.booking_payments WITH(TABLOCKX,HOLDLOCK,NOWAIT);SELECT @Lock=COUNT_BIG(*) FROM dbo.sale_items WITH(TABLOCKX,HOLDLOCK,NOWAIT);IF EXISTS(SELECT 1 FROM dbo.booking_payments p LEFT JOIN dbo.bookings b ON b.id=p.booking_id WHERE b.id IS NULL) OR EXISTS(SELECT 1 FROM dbo.sale_items i LEFT JOIN dbo.sales s ON s.id=i.sale_id WHERE s.id IS NULL) THROW 51155,'LOCAL54F orphan business children require separate review.',1;IF EXISTS(SELECT 1 FROM dbo.sales WITH(TABLOCKX,HOLDLOCK,NOWAIT) WHERE store_id=@Branch AND TRY_CONVERT(uniqueidentifier,shift_id)=@Shift) OR EXISTS(SELECT 1 FROM dbo.bookings WITH(TABLOCKX,HOLDLOCK,NOWAIT) WHERE store_id=@Branch AND TRY_CONVERT(uniqueidentifier,shift_id)=@Shift) OR EXISTS(SELECT 1 FROM dbo.payment_transactions WITH(TABLOCKX,HOLDLOCK,NOWAIT) WHERE store_id=@Branch AND TRY_CONVERT(uniqueidentifier,shift_id)=@Shift) THROW 51155,'LOCAL54F linked business records require separate review.',1;
 INSERT @AncillaryBefore SELECT N'audit_logs' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[audit_logs] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'held_orders' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[held_orders] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'local_operation_receipts' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[local_operation_receipts] WITH(TABLOCKX,HOLDLOCK,NOWAIT) WHERE operation_id<>@Repair ORDER BY [operation_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_baselines' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_baselines] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [branch_id],[shift_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_closing_starts' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_closing_starts] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [shift_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_intents' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_intents] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [intent_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'sync_change_journal' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[sync_change_journal] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [change_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'sync_checkpoints' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[sync_checkpoints] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [organization_id],[branch_id],[entity_type],[direction] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature;
