 IF EXISTS(SELECT * FROM @Other EXCEPT SELECT * FROM @ExpectedOther) OR EXISTS(SELECT * FROM @ExpectedOther EXCEPT SELECT * FROM @Other) THROW 51155,'LOCAL54F branch before-image changed; rebind after three-shift readback.',1;
 DECLARE @BeforeDigest varchar(64),@AfterDigest varchar(64),@OtherDigest varchar(64);
 SELECT @BeforeDigest=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),STRING_AGG(CONVERT(nvarchar(max),table_name+N':'+LOWER(CONVERT(nvarchar(36),id))+N':'+signature),NCHAR(30)) WITHIN GROUP(ORDER BY table_name,CONVERT(nvarchar(36),id)))),2) FROM @ExpectedBefore;
 SELECT @AfterDigest=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),STRING_AGG(CONVERT(nvarchar(max),table_name+N':'+LOWER(CONVERT(nvarchar(36),id))+N':'+signature),NCHAR(30)) WITHIN GROUP(ORDER BY table_name,CONVERT(nvarchar(36),id)))),2) FROM @Proposed;
 SELECT @OtherDigest=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),STRING_AGG(CONVERT(nvarchar(max),table_name+N':'+LOWER(CONVERT(nvarchar(36),id))+N':'+signature),NCHAR(30)) WITHIN GROUP(ORDER BY table_name,CONVERT(nvarchar(36),id)))),2) FROM @Other;
 DECLARE @Note nvarchar(400)=(SELECT note FROM dbo.local_operation_receipts WHERE operation_id=@Repair);
 IF @Note IS NOT NULL BEGIN
  IF ISJSON(@Note)<>1 OR ISNULL(JSON_VALUE(@Note,'$.k'),N'')<>N'LOCAL54F' OR ISNULL(JSON_VALUE(@Note,'$.b'),N'')<>@BeforeDigest OR ISNULL(JSON_VALUE(@Note,'$.a'),N'')<>@AfterDigest OR ISNULL(JSON_VALUE(@Note,'$.o'),N'')<>@OtherDigest OR ISNULL(JSON_VALUE(@Note,'$.p'),N'')<>N'483622B4967BB4B6CABB8C94C8C78A1C3B5B767430F4E07C77D0D52AA1FFA2A1' OR ISNULL(JSON_VALUE(@Note,'$.u'),N'')<>SUSER_SNAME() OR NOT EXISTS(SELECT 1 FROM dbo.local_operation_receipts WHERE operation_id=@Repair AND operation_type=N'cloud_shift_graph_adoption' AND entity_id=CONVERT(nvarchar(36),@Shift) AND CONVERT(nvarchar(40),committed_at,127)=JSON_VALUE(@Note,'$.t')) OR EXISTS(SELECT * FROM @Current EXCEPT SELECT * FROM @Proposed) OR EXISTS(SELECT * FROM @Proposed EXCEPT SELECT * FROM @Current) THROW 51155,'LOCAL54F replay receipt or current graph mismatch.',1;
  COMMIT;SET LOCK_TIMEOUT -1;IF @HadXactAbort=0 SET XACT_ABORT OFF;SELECT N'ALREADY ADOPTED / no new history' result;RETURN;
 END;
 IF EXISTS(SELECT * FROM @Current EXCEPT SELECT * FROM @ExpectedBefore) OR EXISTS(SELECT * FROM @ExpectedBefore EXCEPT SELECT * FROM @Current) THROW 51155,'LOCAL54F target before-image changed.',1;
