 IF EXISTS(SELECT * FROM @Current EXCEPT SELECT * FROM @Other) OR EXISTS(SELECT * FROM @Other EXCEPT SELECT * FROM @Current) THROW 51155,'LOCAL54F unrelated history changed.',1;
 DELETE @ActualMeta;
 INSERT @ActualMeta SELECT N'columns',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'columns|')+canonical.facts)),2) FROM (SELECT t.name table_name,c.column_id,c.name column_name,ty.name type_name,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,c.is_computed,c.collation_name FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'column_id',(CONVERT(nvarchar(max),s.[column_id])) COLLATE DATABASE_DEFAULT),(2,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT),(3,N'type_name',(CONVERT(nvarchar(max),s.[type_name])) COLLATE DATABASE_DEFAULT),(4,N'max_length',(CONVERT(nvarchar(max),s.[max_length])) COLLATE DATABASE_DEFAULT),(5,N'precision',(CONVERT(nvarchar(max),s.[precision])) COLLATE DATABASE_DEFAULT),(6,N'scale',(CONVERT(nvarchar(max),s.[scale])) COLLATE DATABASE_DEFAULT),(7,N'is_nullable',(CASE WHEN s.[is_nullable] IS NULL THEN NULL WHEN s.[is_nullable]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(8,N'is_identity',(CASE WHEN s.[is_identity] IS NULL THEN NULL WHEN s.[is_identity]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(9,N'is_computed',(CASE WHEN s.[is_computed] IS NULL THEN NULL WHEN s.[is_computed]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(10,N'collation_name',(CONVERT(nvarchar(max),s.[collation_name])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'defaults',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'defaults|')+canonical.facts)),2) FROM (SELECT t.name table_name,c.name column_name,d.name constraint_name,d.definition FROM sys.tables t JOIN sys.default_constraints d ON d.parent_object_id=t.object_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=d.parent_column_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT),(2,N'constraint_name',(CONVERT(nvarchar(max),s.[constraint_name])) COLLATE DATABASE_DEFAULT),(3,N'definition',(CONVERT(nvarchar(max),s.[definition])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'checks',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'checks|')+canonical.facts)),2) FROM (SELECT t.name table_name,c.name,c.definition,c.is_disabled,c.is_not_trusted FROM sys.tables t JOIN sys.check_constraints c ON c.parent_object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'definition',(CONVERT(nvarchar(max),s.[definition])) COLLATE DATABASE_DEFAULT),(3,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(4,N'is_not_trusted',(CASE WHEN s.[is_not_trusted] IS NULL THEN NULL WHEN s.[is_not_trusted]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'indexes',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'indexes|')+canonical.facts)),2) FROM (SELECT t.name table_name,i.name index_name,i.type_desc,i.is_unique,i.is_primary_key,i.is_unique_constraint,i.is_disabled,i.has_filter,i.filter_definition,ic.index_column_id,ic.key_ordinal,ic.is_descending_key,ic.is_included_column,c.name column_name FROM sys.tables t JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'index_name',(CONVERT(nvarchar(max),s.[index_name])) COLLATE DATABASE_DEFAULT),(2,N'type_desc',(CONVERT(nvarchar(max),s.[type_desc])) COLLATE DATABASE_DEFAULT),(3,N'is_unique',(CASE WHEN s.[is_unique] IS NULL THEN NULL WHEN s.[is_unique]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(4,N'is_primary_key',(CASE WHEN s.[is_primary_key] IS NULL THEN NULL WHEN s.[is_primary_key]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(5,N'is_unique_constraint',(CASE WHEN s.[is_unique_constraint] IS NULL THEN NULL WHEN s.[is_unique_constraint]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(6,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(7,N'has_filter',(CASE WHEN s.[has_filter] IS NULL THEN NULL WHEN s.[has_filter]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(8,N'filter_definition',(CONVERT(nvarchar(max),s.[filter_definition])) COLLATE DATABASE_DEFAULT),(9,N'index_column_id',(CONVERT(nvarchar(max),s.[index_column_id])) COLLATE DATABASE_DEFAULT),(10,N'key_ordinal',(CONVERT(nvarchar(max),s.[key_ordinal])) COLLATE DATABASE_DEFAULT),(11,N'is_descending_key',(CASE WHEN s.[is_descending_key] IS NULL THEN NULL WHEN s.[is_descending_key]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(12,N'is_included_column',(CASE WHEN s.[is_included_column] IS NULL THEN NULL WHEN s.[is_included_column]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(13,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'foreign_keys',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'foreign_keys|')+canonical.facts)),2) FROM (SELECT t.name table_name,f.name,OBJECT_NAME(f.referenced_object_id) referenced_table,f.is_disabled,f.is_not_trusted,f.delete_referential_action_desc,f.update_referential_action_desc,fc.constraint_column_id,c.name column_name,rc.name referenced_column FROM sys.tables t JOIN sys.foreign_keys f ON f.parent_object_id=t.object_id JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id JOIN sys.columns c ON c.object_id=fc.parent_object_id AND c.column_id=fc.parent_column_id JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'referenced_table',(CONVERT(nvarchar(max),s.[referenced_table])) COLLATE DATABASE_DEFAULT),(3,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(4,N'is_not_trusted',(CASE WHEN s.[is_not_trusted] IS NULL THEN NULL WHEN s.[is_not_trusted]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(5,N'delete_referential_action_desc',(CONVERT(nvarchar(max),s.[delete_referential_action_desc])) COLLATE DATABASE_DEFAULT),(6,N'update_referential_action_desc',(CONVERT(nvarchar(max),s.[update_referential_action_desc])) COLLATE DATABASE_DEFAULT),(7,N'constraint_column_id',(CONVERT(nvarchar(max),s.[constraint_column_id])) COLLATE DATABASE_DEFAULT),(8,N'column_name',(CONVERT(nvarchar(max),s.[column_name])) COLLATE DATABASE_DEFAULT),(9,N'referenced_column',(CONVERT(nvarchar(max),s.[referenced_column])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'keys',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'keys|')+canonical.facts)),2) FROM (SELECT t.name table_name,k.name,k.type_desc,k.unique_index_id FROM sys.tables t JOIN sys.key_constraints k ON k.parent_object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'type_desc',(CONVERT(nvarchar(max),s.[type_desc])) COLLATE DATABASE_DEFAULT),(3,N'unique_index_id',(CONVERT(nvarchar(max),s.[unique_index_id])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'triggers',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'triggers|')+canonical.facts)),2) FROM (SELECT t.name table_name,tr.name,tr.is_disabled,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(tr.object_id))),2) definition_sha256,OBJECT_DEFINITION(tr.object_id) definition FROM sys.tables t JOIN sys.triggers tr ON tr.parent_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'name',(CONVERT(nvarchar(max),s.[name])) COLLATE DATABASE_DEFAULT),(2,N'is_disabled',(CASE WHEN s.[is_disabled] IS NULL THEN NULL WHEN s.[is_disabled]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT),(3,N'definition_sha256',(CONVERT(nvarchar(max),s.[definition_sha256])) COLLATE DATABASE_DEFAULT),(4,N'definition',(CONVERT(nvarchar(max),s.[definition])) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
INSERT @ActualMeta SELECT N'tracking',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'tracking|')+canonical.facts)),2) FROM (SELECT t.name table_name,ct.is_track_columns_updated_on FROM sys.tables t JOIN sys.change_tracking_tables ct ON ct.object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN(N'audit_logs',N'held_orders',N'local_operation_receipts',N'pos_sync_shift_baselines',N'pos_sync_shift_closing_starts',N'pos_sync_shift_intents',N'shift_cash_counts',N'shift_close_events',N'shift_notifications',N'shift_reconciliations',N'shift_variance_alerts',N'shifts',N'sync_change_journal',N'sync_checkpoints')) s CROSS APPLY(SELECT STRING_AGG(CONVERT(nvarchar(max),c.name+N'='+CASE WHEN c.value IS NULL THEN N'N' ELSE N'V'+CONVERT(nvarchar(20),DATALENGTH(c.value)/2)+N':'+c.value END),N'|') WITHIN GROUP(ORDER BY c.ordinal) facts FROM(VALUES (0,N'table_name',(CONVERT(nvarchar(max),s.[table_name])) COLLATE DATABASE_DEFAULT),(1,N'is_track_columns_updated_on',(CASE WHEN s.[is_track_columns_updated_on] IS NULL THEN NULL WHEN s.[is_track_columns_updated_on]=1 THEN N'true' ELSE N'false' END) COLLATE DATABASE_DEFAULT)) c(ordinal,name,value)) canonical;
 IF EXISTS(SELECT kind,signature,COUNT_BIG(*) n FROM @ActualMeta GROUP BY kind,signature EXCEPT SELECT kind,signature,COUNT_BIG(*) FROM @ExpectedMeta GROUP BY kind,signature) OR EXISTS(SELECT kind,signature,COUNT_BIG(*) FROM @ExpectedMeta GROUP BY kind,signature EXCEPT SELECT kind,signature,COUNT_BIG(*) FROM @ActualMeta GROUP BY kind,signature) THROW 51155,'LOCAL54F metadata changed during adoption.',1;
 DECLARE @Committed datetimeoffset(7)=SYSDATETIMEOFFSET();
 DECLARE @Receipt nvarchar(max)=(SELECT N'LOCAL54F' k,@BeforeDigest b,@AfterDigest a,@OtherDigest o,N'483622B4967BB4B6CABB8C94C8C78A1C3B5B767430F4E07C77D0D52AA1FFA2A1' p,SUSER_SNAME() u,CONVERT(nvarchar(40),@Committed,127) t FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 IF DATALENGTH(@Receipt)>800 THROW 51155,'LOCAL54F honest receipt exceeds existing capacity.',1;
 INSERT dbo.local_operation_receipts(operation_id,operation_type,entity_id,note,committed_at) VALUES(@Repair,N'cloud_shift_graph_adoption',CONVERT(nvarchar(36),@Shift),@Receipt,@Committed);
 IF @@ROWCOUNT<>1 THROW 51155,'LOCAL54F receipt insert failed.',1;
 INSERT @AncillaryAfter SELECT N'audit_logs' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[audit_logs] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'held_orders' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[held_orders] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'local_operation_receipts' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[local_operation_receipts] WITH(TABLOCKX,HOLDLOCK,NOWAIT) WHERE operation_id<>@Repair ORDER BY [operation_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_baselines' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_baselines] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [branch_id],[shift_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_closing_starts' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_closing_starts] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [shift_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'pos_sync_shift_intents' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[pos_sync_shift_intents] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [intent_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'sync_change_journal' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[sync_change_journal] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [change_id] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature
UNION ALL
SELECT N'sync_checkpoints' table_name,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM dbo.[sync_checkpoints] WITH(TABLOCKX,HOLDLOCK,NOWAIT)  ORDER BY [organization_id],[branch_id],[entity_type],[direction] FOR JSON PATH,INCLUDE_NULL_VALUES))),2) signature;
 IF EXISTS(SELECT * FROM @AncillaryBefore EXCEPT SELECT * FROM @AncillaryAfter) OR EXISTS(SELECT * FROM @AncillaryAfter EXCEPT SELECT * FROM @AncillaryBefore) THROW 51155,'LOCAL54F queue/checkpoint/proof/audit or existing receipts changed.',1;
 COMMIT;SET LOCK_TIMEOUT -1;IF @HadXactAbort=0 SET XACT_ABORT OFF;SELECT N'ADOPTED EXISTING CLOUD GRAPH / not full branch recovery' result;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK;SET LOCK_TIMEOUT -1;IF @HadXactAbort=0 SET XACT_ABORT OFF;THROW;
END CATCH;
